from __future__ import annotations

from typing import Any, Callable, Dict, List, Mapping, Optional, Tuple, Union

from pyspark.pipelines.source_code_location import SourceCodeLocation
from pyspark.sql.types import StructType


QueryFunction = Callable[[], Any]


def _get_active_connect_session_and_client() -> Tuple[Any, Any]:
    """Return (session, client) of the active Spark Connect session.

    Mirrors the universe `SparkConnectGraphElementRegistry` pattern of resolving
    the active Connect session lazily.
    """
    from pyspark.sql.connect.session import SparkSession as ConnectSession

    session = ConnectSession.active()
    client = getattr(session, "_client", None)
    if client is None:  # defensive
        raise RuntimeError(
            "pyspark.pipelines standalone dispatch requires an active Spark "
            "Connect session, but `SparkSession.active()._client` is None."
        )
    return session, client


def _normalize_replace_where(replace_where: Any, client: Any) -> Any:
    """Accept str | Column for replace_where, return a pb2.Expression."""
    if replace_where is None:
        return None
    from pyspark.sql.connect.column import Column
    from pyspark.sql.connect import functions as F

    col = F.expr(replace_where) if isinstance(replace_where, str) else replace_where
    if not isinstance(col, Column):
        raise TypeError(
            "replace_where must be a SQL string or a Column; "
            f"got {type(col).__name__}"
        )
    return col.to_plan(client)


def _build_define_output(
    *,
    output_kind: str,
    name: str,
    comment: Optional[str],
    table_properties: Mapping[str, str],
    partition_cols: Optional[List[str]],
    cluster_by: Optional[List[str]],
    cluster_by_auto: bool,
    schema: Optional[Union[str, StructType]],
    format: Optional[str],
    path: Optional[str],
    row_filter: Optional[str],
    private: bool,
    refresh_policy: Optional[str],
    auto_ttl: Optional[Mapping[str, Any]],
    spark_conf: Mapping[str, str],
    source_code_location: Optional[SourceCodeLocation],
) -> Any:
    """Build a `PipelineCommand.DefineOutput` whose extension field carries
    universe-only fields (cluster_by_auto, row_filter, private, path, sql_conf,
    refresh_policy, auto_ttl) via an `EdgeTableDetails` message.
    """
    import pyspark.sql.connect.proto as pb2
    from pyspark.sql.connect.proto import pipelines_extensions_pb2 as pipelines_ext_pb2
    from pyspark.sql.connect.types import pyspark_types_to_proto_types
    from google.protobuf import any_pb2

    if output_kind == "table":
        output_type = pb2.OutputType.TABLE
    elif output_kind == "materialized_view":
        output_type = pb2.OutputType.MATERIALIZED_VIEW
    else:
        raise ValueError(
            f"unsupported output_kind={output_kind!r}; expected 'table' or 'materialized_view'"
        )

    schema_string = None
    schema_data_type = None
    if schema is not None:
        if isinstance(schema, str):
            schema_string = schema
        elif isinstance(schema, StructType):
            schema_data_type = pyspark_types_to_proto_types(schema)
        else:
            raise TypeError(
                f"schema must be str or StructType; got {type(schema).__name__}"
            )

    table_details = pb2.PipelineCommand.DefineOutput.TableDetails(
        table_properties=dict(table_properties) if table_properties else {},
        partition_cols=list(partition_cols) if partition_cols else [],
        format=format,  # type: ignore[arg-type]
        schema_string=schema_string,  # type: ignore[arg-type]
        schema_data_type=schema_data_type,  # type: ignore[arg-type]
        clustering_columns=list(cluster_by) if cluster_by else [],
    )

    refresh_policy_proto: Optional[int] = None
    if refresh_policy is not None:
        # Mirrors `pysparkpipelines.dataset.RefreshPolicy` Literal.
        refresh_policy_map = {
            "auto": pipelines_ext_pb2.REFRESH_POLICY_AUTO,
            "incremental": pipelines_ext_pb2.REFRESH_POLICY_INCREMENTAL,
            "incremental_strict": pipelines_ext_pb2.REFRESH_POLICY_INCREMENTAL_STRICT,
            "full": pipelines_ext_pb2.REFRESH_POLICY_FULL,
        }
        if refresh_policy not in refresh_policy_map:
            raise ValueError(
                f"refresh_policy must be one of {sorted(refresh_policy_map)}; "
                f"got {refresh_policy!r}"
            )
        refresh_policy_proto = refresh_policy_map[refresh_policy]

    edge_table_details = pipelines_ext_pb2.EdgeTableDetails(
        table_details=table_details,
        cluster_by_auto=cluster_by_auto if cluster_by_auto else None,  # type: ignore[arg-type]
        private=True if private else None,  # type: ignore[arg-type]
        row_filter=row_filter,  # type: ignore[arg-type]
        path=path,  # type: ignore[arg-type]
        sql_conf=dict(spark_conf) if spark_conf else {},
        refresh_policy=refresh_policy_proto,  # type: ignore[arg-type]
        auto_ttl=pipelines_ext_pb2.AutoTTLConfig(**auto_ttl) if auto_ttl else None,  # type: ignore[arg-type]
    )
    extension = any_pb2.Any()
    extension.Pack(edge_table_details)

    return pb2.PipelineCommand.DefineOutput(
        output_name=name,
        output_type=output_type,
        comment=comment,  # type: ignore[arg-type]
        extension=extension,
        source_code_location=_to_proto_source_code_location(source_code_location),  # type: ignore[arg-type]
    )


def _build_define_flow(
    *,
    target_name: str,
    relation: Any,
    spark_conf: Mapping[str, str],
    comment: Optional[str],
    replace_where_expr: Any,
    import_checkpoint: Optional[str],
    source_code_location: Optional[SourceCodeLocation],
) -> Any:
    """Build a `PipelineCommand.DefineFlow` whose extension field carries
    universe-only fields (replace_where, comment) via an
    `EdgeWriteRelationFlowDetails` message.
    """
    import pyspark.sql.connect.proto as pb2
    from pyspark.sql.connect.proto import pipelines_extensions_pb2 as pipelines_ext_pb2
    from google.protobuf import any_pb2

    edge_flow_details = pipelines_ext_pb2.EdgeWriteRelationFlowDetails(
        relation_flow_details=pb2.PipelineCommand.DefineFlow.WriteRelationFlowDetails(
            relation=relation,
        ),
        comment=comment,  # type: ignore[arg-type]
        replace_where=replace_where_expr,  # type: ignore[arg-type]
        import_checkpoint_path=import_checkpoint,  # type: ignore[arg-type]
    )
    extension = any_pb2.Any()
    extension.Pack(edge_flow_details)

    return pb2.PipelineCommand.DefineFlow(
        target_dataset_name=target_name,
        sql_conf=dict(spark_conf) if spark_conf else {},
        extension=extension,
        source_code_location=_to_proto_source_code_location(source_code_location),  # type: ignore[arg-type]
    )


def _to_proto_source_code_location(
    loc: Optional[SourceCodeLocation],
) -> Any:
    """None-safe variant of `SparkConnectGraphElementRegistry.source_code_location_to_proto`
    (`runtime/python/pyspark/pipelines/spark_connect_graph_element_registry.py`)."""
    if loc is None:
        return None
    import pyspark.sql.connect.proto as pb2

    return pb2.SourceCodeLocation(file_name=loc.filename, line_number=loc.line_number)


def _build_command(
    *,
    define_output: Any,
    define_flow: Any,
    full_refresh: bool = False,
) -> Any:
    """Assemble the top-level `Command` -> `PipelineCommand.ExecuteOutputFlows`
    message. Uses only the OSS `ExecuteOutputFlows` shape; no edge extensions.
    """
    import pyspark.sql.connect.proto as pb2

    inner = pb2.PipelineCommand.ExecuteOutputFlows(
        define_output=define_output,
        define_flows=[define_flow],
        full_refresh=full_refresh,
    )
    pipeline_command = pb2.PipelineCommand(execute_output_flows=inner)

    cmd = pb2.Command()
    cmd.pipeline_command.CopyFrom(pipeline_command)
    return cmd


def _resolve_output_kind(
    decorator: str,
    df_is_streaming: bool,
    *,
    resolved_name: str = "",
) -> str:
    """Resolve the user's *decorator name* to the final OutputType based on
    the DataFrame's streaming-ness.

    Mirrors the universe `pysparkpipelines.api._table` semantics
    """
    if decorator == "table" and not df_is_streaming:
        return "materialized_view"
    if decorator == "materialized_view" and df_is_streaming:
        name_part = f" {resolved_name!r}" if resolved_name else ""
        raise ValueError(
            f"@materialized_view{name_part} query function returned a "
            f"streaming DataFrame; @materialized_view requires a batch query. "
            f"Use @table for streaming sources."
        )
    return decorator


def dispatch_standalone(
    output_kind: str,
    decorated: QueryFunction,
    *,
    resolved_name: str,
    comment: Optional[str] = None,
    spark_conf: Optional[Dict[str, str]] = None,
    table_properties: Optional[Dict[str, str]] = None,
    partition_cols: Optional[List[str]] = None,
    cluster_by: Optional[List[str]] = None,
    cluster_by_auto: bool = False,
    schema: Optional[Union[str, StructType]] = None,
    format: Optional[str] = None,
    path: Optional[str] = None,
    row_filter: Optional[str] = None,
    private: bool = False,
    refresh_policy: Optional[str] = None,
    import_checkpoint: Optional[str] = None,
    replace_where: Any = None,
    auto_ttl: Optional[Mapping[str, Any]] = None,
    full_refresh: bool = False,
    source_code_location: Optional[SourceCodeLocation] = None,
) -> None:
    """Eagerly invoke the user's query function and dispatch a
    `PipelineCommand.ExecuteOutputFlows` over Spark Connect.

    Called from `pyspark.pipelines.api.{table, materialized_view}` when no
    grouped-pipeline `GraphElementRegistry` is active.

    `output_kind` is the **decorator name** the user invoked
    (`"table"` / `"materialized_view"`), not the final wire type. For
    `@table` we infer the actual kind from `df.isStreaming`: a streaming
    DataFrame yields a streaming table; a batch DataFrame yields a
    materialized view. `@materialized_view` is strictly batch and rejects a
    streaming body. This mirrors the universe `pysparkpipelines.api._table`
    semantics (`allow_streaming_query_function` + `declared_materialized_view`
    + engine flow inference) without round-tripping through a CLT.
    """
    if not callable(decorated):
        raise TypeError(
            f"@{output_kind} must wrap a callable that returns a DataFrame; "
            f"got {type(decorated).__name__}"
        )

    _session, client = _get_active_connect_session_and_client()

    df = decorated()
    if not hasattr(df, "_plan"):
        raise TypeError(
            f"@{output_kind} query function must return a Spark Connect "
            f"DataFrame; got {type(df).__name__}"
        )

    df_is_streaming = bool(getattr(df, "isStreaming", False))
    output_kind = _resolve_output_kind(
        output_kind, df_is_streaming, resolved_name=resolved_name
    )

    relation = df._plan.plan(client)

    replace_where_expr = _normalize_replace_where(replace_where, client)

    define_output = _build_define_output(
        output_kind=output_kind,
        name=resolved_name,
        comment=comment,
        table_properties=table_properties or {},
        partition_cols=partition_cols,
        cluster_by=cluster_by,
        cluster_by_auto=cluster_by_auto,
        schema=schema,
        format=format,
        path=path,
        row_filter=row_filter,
        private=private,
        refresh_policy=refresh_policy,
        auto_ttl=auto_ttl,
        spark_conf=spark_conf or {},
        source_code_location=source_code_location,
    )
    define_flow = _build_define_flow(
        target_name=resolved_name,
        relation=relation,
        spark_conf=spark_conf or {},
        comment=comment,
        replace_where_expr=replace_where_expr,
        import_checkpoint=import_checkpoint,
        source_code_location=source_code_location,
    )
    cmd = _build_command(
        define_output=define_output,
        define_flow=define_flow,
        full_refresh=full_refresh,
    )
    client.execute_command(cmd)
